using OpenIGI.Core.Diagnostics;
using System.Globalization;
using System.Text;

namespace OpenIGI.Presentation.Cameras;

/// <summary>
/// Writes <c>Assets/menu-cameras.json</c> from places found in the levels, so the shots a mission's
/// backdrop cycles between become reviewable, editable data rather than something recomputed every run.
/// </summary>
/// <remarks>
/// <para>
/// The file is generated by <c>-poidump</c> and then owned by hand. Everything in it can be edited — a
/// place moved a few metres, an orbit pulled in, a dull one replaced — and nothing regenerates it behind
/// the author's back; a mission with no entry falls back to finding its places at load, which is what
/// keeps a mod's levels working without anybody running the tool.
/// </para>
/// <para>
/// Written by hand rather than through <see cref="System.Text.Json"/> so the result is laid out for a
/// person to read and diff: one place per line, coordinates to one decimal, missions in campaign order.
/// A serialiser's output is correct and unreadable, and this file's whole purpose is to be edited.
/// </para>
/// </remarks>
public static class ShowcasePointFile
{
    private const string LogCategory = "Menu";

    /// <summary>One mission's entry: the orbit style, and the places the backdrop cycles between.</summary>
    /// <param name="MissionId">The mission id.</param>
    /// <param name="Name">The mission's display name, written as a comment for whoever edits the file.</param>
    /// <param name="Style">The orbit's speed, start angle and pitch bias, shared by every place.</param>
    /// <param name="Points">The places, in the order they are shown.</param>
    public readonly record struct Entry(
        int MissionId,
        string Name,
        MenuCameraSpec Style,
        IReadOnlyList<ShowcasePoint> Points);

    /// <summary>Writes the entries out as the menu-camera file.</summary>
    /// <param name="path">Where to write.</param>
    /// <param name="entries">The missions, in the order they should appear.</param>
    /// <param name="logger">Where to report the write.</param>
    /// <exception cref="ArgumentNullException">An argument is <see langword="null"/>.</exception>
    public static void Write(string path, IReadOnlyList<Entry> entries, IOpenIgiLogger? logger = null)
    {
        ArgumentNullException.ThrowIfNull(path);
        ArgumentNullException.ThrowIfNull(entries);

        var text = new StringBuilder();
        text.AppendLine("[");

        for (int i = 0; i < entries.Count; i++)
        {
            Entry entry = entries[i];
            text.AppendLine("  {");
            text.AppendLine(Invariant($"    \"mission\": {entry.MissionId},"));
            text.AppendLine(Invariant($"    \"comment\": \"{Escape(entry.Name)}\","));
            text.AppendLine(Invariant($"    \"radius\": {entry.Style.Radius:0.#},"));
            text.AppendLine(Invariant($"    \"height\": {entry.Style.Height:0.#},"));
            text.AppendLine(Invariant($"    \"speed\": {entry.Style.SpeedRadiansPerSecond:0.###},"));
            text.AppendLine(Invariant($"    \"startAngle\": {entry.Style.StartAngleRadians:0.###},"));
            text.AppendLine(Invariant($"    \"pitchBias\": {entry.Style.PitchBiasRadians:0.###},"));
            text.AppendLine("    \"points\": [");

            for (int p = 0; p < entry.Points.Count; p++)
            {
                ShowcasePoint point = entry.Points[p];
                string comma = p == entry.Points.Count - 1 ? string.Empty : ",";
                text.Append(Invariant(
                    $"      {{ \"x\": {point.Centre.X:0.#}, \"y\": {point.Centre.Y:0.#}, \"z\": {point.Centre.Z:0.#}"));
                text.AppendLine(Invariant(
                    $", \"radius\": {point.Orbit.Radius:0.#}, \"height\": {point.Orbit.Height:0.#} }}{comma}"));
            }

            text.AppendLine("    ]");
            text.AppendLine(i == entries.Count - 1 ? "  }" : "  },");
        }

        text.AppendLine("]");

        string? directory = Path.GetDirectoryName(path);
        if (!string.IsNullOrEmpty(directory))
        {
            Directory.CreateDirectory(directory);
        }

        File.WriteAllText(path, text.ToString());
        logger?.Information(
            LogCategory,
            $"Wrote {entries.Count} mission(s) of showcase points to {path}.");
    }

    private static string Invariant(FormattableString text) => text.ToString(CultureInfo.InvariantCulture);

    private static string Escape(string text) => text.Replace("\\", "\\\\", StringComparison.Ordinal)
        .Replace("\"", "\\\"", StringComparison.Ordinal);
}
